export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const reason = String(inputs.reason === undefined || inputs.reason === null ? '' : inputs.reason);

  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };

  const keyByReason = {
    not_found: 'event.card.not_found',
    event_cancelled: 'reg.event_cancelled',
    event_finished: 'reg.event_finished',
    not_published: 'reg.not_published',
    deadline_passed: 'reg.deadline_passed',
    no_seats: 'reg.no_seats'
  };
  const key = keyByReason[reason] || 'common.err.generic';
  const raw = String(texts[key] || key);
  const when = fmt(String(inputs.deadlineAt || ''));
  const text = raw.split('{when}').join(when);

  return { text: text, reason: reason };
};

