export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  // cardMessageId и шаг сессии живут в JSON внутри sessions.draft, а не
  // отдельными колонками (схема заморожена с W1). Шаг ob_consent — вход
  // онбординга: reg-profile ждёт ob:continue/ob:agree/ob:details.
  // Правка (2026-09-20): `step` реально не писался в draft — reg-profile
  // читает step из draft.step, а не из отдельной колонки sessions.step,
  // поэтому каждый колбэк уходил в ignore (онбординг выглядел «скипнутым»).
  const cardMessageId = Number(inputs.cardMessageId);
  const draft = {
    eventId: str(inputs.eventId),
    utm: str(inputs.utm),
    cardMessageId: isFinite(cardMessageId) && cardMessageId > 0 ? cardMessageId : 0,
    step: 'ob_consent'
  };
  return { draft: JSON.stringify(draft), cardMessageId: draft.cardMessageId };
};

export const code = async (inputs) => {
  // W50 / PAR-8: вход в онбординг — карточка события + «зачем данные» + Дальше.
  // Согласие переспрашиваем даже при consent_pdn=true: старый объём согласия
  // покрывал регистрацию, а не поля профиля (должность/компания/город).
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] || key);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const lat = Number(inputs.lat);
  const lon = Number(inputs.lon);
  const hasGeo = isFinite(lat) && isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
  const mapsUrl = hasGeo ? ('https://yandex.uz/maps/?ll=' + lon + '%2C' + lat + '&z=17&pt=' + lon + '%2C' + lat) : '';
  const lines = [];
  if (str(inputs.title)) lines.push('*' + esc(str(inputs.title)) + '*');
  if (str(inputs.description)) lines.push(esc(str(inputs.description)));
  const facts = [];
  if (str(inputs.startsAt)) facts.push('📅 ' + esc(fmt(str(inputs.startsAt))) + (str(inputs.endsAt) ? ' — ' + esc(fmt(str(inputs.endsAt))) : ''));
  if (str(inputs.address)) facts.push('📍 ' + esc(str(inputs.address)));
  if (mapsUrl) facts.push('🗺 [Открыть на карте](' + mapsUrl + ')');
  if (str(inputs.regDeadlineAt)) facts.push('⏳ ' + esc(t('event.card.deadline_short', { when: fmt(str(inputs.regDeadlineAt)) })));
  if (facts.length) lines.push(facts.join('\n'));
  lines.push(esc(t('onb.why')));
  const replyMarkup = {
    inline_keyboard: [[{ text: t('onb.btn.continue'), callback_data: 'ob:continue' }]]
  };
  return { text: lines.join('\n\n'), replyMarkup: replyMarkup, mapsUrl: mapsUrl, now: new Date().toISOString() };
};

