export const code = async (inputs) => {
  // Q32: если чтение события или регистраций упало (continueOnFailure на
  // step_1/step_2), не продолжаем логику на пустых данных — это выглядело
  // бы как "событие не найдено", хотя на самом деле сбой чтения. Единая
  // декларируемая причина 'internal_error' уходит в существующую ветку
  // "declined", где keyByReason не находит ключ и берёт fallback
  // common.err.generic (см. step_5) — без второго сообщения.
  if (inputs.eventReadError || inputs.regReadError) {
    return { outcome: 'declined', reason: 'internal_error', deadlineAt: '', photoFileId: '' };
  }

  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };

  const eventRows = arr(inputs.eventRecords).map(flat);
  const ev = eventRows[0];
  const telegramId = String(inputs.telegramId === undefined || inputs.telegramId === null ? '' : inputs.telegramId);
  const regRows = arr(inputs.regRecords).map(flat);
  const myRow = regRows.find((r) => String(r.telegram_id || '') === telegramId);
  const registeredCount = regRows.filter((r) => String(r.status || '') === 'registered').length;

  if (myRow && String(myRow.status || '') === 'registered') {
    return { outcome: 'existing', title: ev ? (ev.title || '') : '', photoFileId: '' };
  }

  if (!ev) return { outcome: 'declined', reason: 'not_found', deadlineAt: '', photoFileId: '' };
  const status = ev.status || '';
  if (status === 'cancelled') return { outcome: 'declined', reason: 'event_cancelled', deadlineAt: '', photoFileId: '' };
  if (status === 'finished') return { outcome: 'declined', reason: 'event_finished', deadlineAt: '', photoFileId: '' };
  if (status !== 'published') return { outcome: 'declined', reason: 'not_published', deadlineAt: '', photoFileId: '' };

  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  const nowMs = Date.now();
  const deadlineMs = ev.reg_deadline_at ? parseIso(ev.reg_deadline_at) : NaN;
  if (isFinite(deadlineMs) && nowMs > deadlineMs) return { outcome: 'declined', reason: 'deadline_passed', deadlineAt: ev.reg_deadline_at || '', photoFileId: '' };

  const capacityRaw = ev.capacity;
  const capacity = (capacityRaw === '' || capacityRaw === undefined) ? NaN : Number(capacityRaw);
  const overbookRaw = ev.overbook_pct;
  const overbook = (overbookRaw === '' || overbookRaw === undefined || !isFinite(Number(overbookRaw))) ? 40 : Number(overbookRaw);
  if (isFinite(capacity)) {
    const limit = Math.ceil(capacity * (1 + overbook / 100));
    if (registeredCount >= limit) return { outcome: 'declined', reason: 'no_seats', deadlineAt: '', photoFileId: '' };
  }

  const base = {
    title: ev.title || '', description: ev.description || '', address: ev.address || '',
    startsAt: ev.starts_at || '', endsAt: ev.ends_at || '', regDeadlineAt: ev.reg_deadline_at || '',
    lat: ev.lat || '', lon: ev.lon || '',
    photoFileId: ev.photo_file_id || ''
  };
  // W50 / PAR-8: первое касание без заполненного профиля — в онбординг;
  // профиль заполнен — регистрация в один тап (consent уже дан, повторный
  // вопрос противоречит ADR-0032). Профиль неполон, даже если consent_pdn
  // уже true (регистрации до онбординга): таких ведём с why-карточки, но
  // согласие не переспрашиваем (consentGiven).
  const userRow = arr(inputs.userRows).map(flat).find((r) => String(r.telegram_id || '') === telegramId) || {};
  const profileDone = String(userRow.profile_completed_at || '') !== '';
  if (profileDone) {
    const nm = (String(userRow.profile_first_name || '').trim() + ' ' + String(userRow.profile_last_name || '').trim()).trim();
    const work = String(userRow.position || '').trim();
    return Object.assign({ outcome: 'register', profileLine: nm + (work ? ' · ' + work : ''), consentGiven: true }, base);
  }
  return Object.assign({
    outcome: 'onboard',
    consentGiven: String(userRow.consent_pdn || '') === 'true'
  }, base);
};
